"""Möbius function μ(n) for all n up to N, computed via a modified sieve."""


def mobius(N: int) -> list[int]:
    """Return a list mu where mu[n] = μ(n) for 0 <= n <= N.

    Uses a sieve that tracks the smallest prime factor and a sign flag.
    Time: O(N log log N)  |  Space: O(N)
    """
    if N < 0:
        raise ValueError("N must be non-negative")

    mu = [0] * (N + 1)
    mu[1] = 1

    # smallest prime factor for each number
    spf = list(range(N + 1))

    for i in range(2, N + 1):
        if spf[i] == i:  # i is prime
            for j in range(i, N + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Compute μ using the factorisation recorded in spf.
    for n in range(2, N + 1):
        p = spf[n]
        m = n // p
        if m % p == 0:
            # p^2 divides n → μ(n) = 0
            mu[n] = 0
        else:
            # n = p * m where p ∤ m → μ(n) = -μ(m)
            mu[n] = -mu[m]

    return mu


if __name__ == "__main__":
    N = 50
    mu = mobius(N)
    for n in range(1, N + 1):
        print(f"μ({n:2d}) = {mu[n]:+d}" if mu[n] else f"μ({n:2d}) =  0")
